using System.Diagnostics.CodeAnalysis;
using System.Security.Cryptography;

namespace Omnichannel.Application.Products;

/// <summary>
/// The keys of product images in the bucket. Two kinds, both generated by the server only, ids as lower-case GUIDs
/// with dashes:
/// <list type="bullet">
/// <item>
/// <b>Staging</b> <c>uploads/products/{productId}/{uploadId}</c> - where a presigned upload link writes. A client
/// sends this key back to confirm its upload; nothing a product refers to is ever stored under it, so the link - valid
/// for a few minutes more - can never change an image that was confirmed.
/// </item>
/// <item>
/// <b>Final</b> <c>products/{productId}/{objectId}</c> - what a product's <c>ImageKey</c> names (the only kind before
/// task 026c: keys stored earlier stay valid as they are). Written once, by the confirmation that copies the upload
/// there; no link and no client can write it.
/// </item>
/// </list>
/// A final object id made here starts with a digest of the upload id it was copied from and ends with random bits:
/// two confirmations of one upload never write the same object, and a repeated confirmation is still recognised
/// (<see cref="IsFinalOf"/>) without storing anything more than the key.
/// </summary>
public static class ProductImageKey
{
    /// <summary>Prefix of every final key.</summary>
    public const string FinalPrefix = "products/";

    /// <summary>Prefix of every staging key.</summary>
    public const string StagingPrefix = "uploads/products/";

    private const string GuidFormat = "D";

    /// <summary>The leading bytes of a final object id that come from the upload id (the version nibble in the seventh).</summary>
    private const int UploadTagLength = 8;

    /// <summary>A new staging key for an upload of <paramref name="productId"/> (the upload id is a UUIDv7).</summary>
    public static string NewStagingFor(Guid productId) =>
        $"{StagingPrefix}{productId.ToString(GuidFormat)}/{Guid.CreateVersion7().ToString(GuidFormat)}";

    /// <summary>
    /// A new final key for a copy of the upload <paramref name="uploadId"/> of <paramref name="productId"/>: different
    /// on every call, and recognisable as a copy of that upload.
    /// </summary>
    public static string NewFinalFor(Guid productId, Guid uploadId)
    {
        Span<byte> id = stackalloc byte[16];
        RandomNumberGenerator.Fill(id);
        UploadTag(uploadId, id);
        // RFC 9562: variant 10xx; the version (8, "custom") is part of the tag.
        id[8] = (byte)((id[8] & 0x3F) | 0x80);
        return $"{FinalPrefix}{productId.ToString(GuidFormat)}/{new Guid(id, bigEndian: true).ToString(GuidFormat)}";
    }

    /// <summary>
    /// True when <paramref name="key"/> is a well-formed <b>staging</b> key of <paramref name="productId"/>: the only
    /// keys a confirmation accepts.
    /// </summary>
    public static bool BelongsTo([NotNullWhen(true)] string? key, Guid productId) =>
        TryParseStaging(key, out var owner, out _) && owner == productId;

    /// <summary>Product and upload id of a well-formed staging key. Anything but the exact generated form is rejected.</summary>
    public static bool TryParseStaging([NotNullWhen(true)] string? key, out Guid productId, out Guid uploadId) =>
        TryParse(key, StagingPrefix, out productId, out uploadId);

    /// <summary>Product and object id of a well-formed final key. Anything but the exact generated form is rejected.</summary>
    public static bool TryParseFinal([NotNullWhen(true)] string? key, out Guid productId, out Guid objectId) =>
        TryParse(key, FinalPrefix, out productId, out objectId);

    /// <summary>
    /// True when <paramref name="finalKey"/> is a final key that <see cref="NewFinalFor"/> made for the upload
    /// <paramref name="uploadId"/>. Never true for a key stored before task 026c (their object ids are UUIDv7, whose
    /// version differs).
    /// </summary>
    public static bool IsFinalOf(string? finalKey, Guid uploadId)
    {
        if (!TryParseFinal(finalKey, out _, out var objectId))
        {
            return false;
        }

        Span<byte> id = stackalloc byte[16];
        Span<byte> tag = stackalloc byte[16];
        objectId.TryWriteBytes(id, bigEndian: true, out _);
        UploadTag(uploadId, tag);
        return id[..UploadTagLength].SequenceEqual(tag[..UploadTagLength]);
    }

    /// <summary>
    /// Writes the first <see cref="UploadTagLength"/> bytes of an object id for <paramref name="uploadId"/>: the start
    /// of its SHA-256, with the UUID version set to 8 (60 bits of the digest remain).
    /// </summary>
    private static void UploadTag(Guid uploadId, Span<byte> objectId)
    {
        Span<byte> upload = stackalloc byte[16];
        Span<byte> digest = stackalloc byte[SHA256.HashSizeInBytes];
        uploadId.TryWriteBytes(upload, bigEndian: true, out _);
        SHA256.HashData(upload, digest);
        digest[..UploadTagLength].CopyTo(objectId);
        objectId[6] = (byte)((objectId[6] & 0x0F) | 0x80);
    }

    private static bool TryParse(string? key, string prefix, out Guid productId, out Guid objectId)
    {
        (productId, objectId) = (Guid.Empty, Guid.Empty);
        if (key is null || !key.StartsWith(prefix, StringComparison.Ordinal))
        {
            return false;
        }

        var parts = key[prefix.Length..].Split('/');
        return parts.Length == 2
            && IsCanonical(parts[0], out productId)
            && IsCanonical(parts[1], out objectId);
    }

    // Guid.TryParseExact accepts upper case; the generated form is lower case, and only that one names the object.
    private static bool IsCanonical(string text, out Guid value) =>
        Guid.TryParseExact(text, GuidFormat, out value) && value != Guid.Empty && value.ToString(GuidFormat) == text;
}
